<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --color-page: #f5f7fb;
        --color-surface: #ffffff;
        --color-text: #111827;
        --color-muted: #4b5563;
        --color-border: #cbd5e1;
        --color-accent: #2457d6;
        --color-accent-dark: #1d45ad;
        --color-focus: #f59e0b;
        --shadow-card: 0 24px 60px rgba(15, 23, 42, 0.14);
        --radius-lg: 28px;
        --radius-md: 18px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        color: var(--color-text);
        background:
          radial-gradient(circle at top left, #dbeafe 0, transparent 32rem),
          linear-gradient(135deg, #f8fafc 0%, var(--color-page) 100%);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--color-text);
        color: var(--color-surface);
        padding: 0.75rem 1rem;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      main {
        width: min(100%, 44rem);
      }

      .card {
        overflow: hidden;
        border: 1px solid rgba(203, 213, 225, 0.9);
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .hero {
        padding: clamp(2rem, 7vw, 4rem) clamp(1.5rem, 6vw, 3.5rem) 1rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--color-accent);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3.4rem);
        letter-spacing: -0.055em;
        line-height: 0.95;
      }

      .intro {
        max-width: 34rem;
        margin: 1rem 0 0;
        color: var(--color-muted);
        font-size: 1.05rem;
      }

      form {
        padding: 1rem clamp(1.5rem, 6vw, 3.5rem) clamp(1.5rem, 6vw, 3rem);
      }

      fieldset {
        margin: 0;
        border: 0;
        padding: 0;
      }

      legend {
        margin-bottom: 1rem;
        color: var(--color-text);
        font-size: 1.1rem;
        font-weight: 800;
      }

      .form-field {
        border-radius: var(--radius-md);
        background: #f8fafc;
        padding: 1.25rem;
      }

      .radio-options {
        display: grid;
        gap: 0.75rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        border: 1px solid var(--color-border);
        border-radius: 16px;
        background: var(--color-surface);
        padding: 1rem;
        color: var(--color-text);
        cursor: pointer;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      .radio-option:hover {
        border-color: var(--color-accent);
        box-shadow: 0 10px 24px rgba(36, 87, 214, 0.12);
        transform: translateY(-1px);
      }

      input[type="radio"] {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0;
        accent-color: var(--color-accent);
        flex: 0 0 auto;
      }

      .radio-option:has(input[type="radio"]:checked) {
        border-color: var(--color-accent);
        box-shadow: inset 0 0 0 1px var(--color-accent);
      }

      input[type="radio"]:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 4px;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 1rem;
        margin-top: 1.25rem;
      }

      button {
        border: 0;
        border-radius: 999px;
        background: var(--color-accent);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        padding: 0.9rem 1.35rem;
        transition:
          background 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--color-accent-dark);
        transform: translateY(-1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--color-muted);
        font-weight: 700;
      }

      @media (max-width: 30rem) {
        .page-shell {
          padding: 1rem;
        }

        .card {
          border-radius: 20px;
        }

        .actions {
          align-items: stretch;
          flex-direction: column;
        }

        button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .radio-option,
        button {
          border: 1px solid ButtonBorder;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <div class="page-shell">
      <main id="main-content">
        <section class="card" aria-labelledby="page-title">
          <div class="hero">
            <p class="eyebrow">Preferences</p>
            <h1 id="page-title">Stay in the loop your way</h1>
            <p class="intro">
              Choose the notification channel that works best for you. You can update this preference later.
            </p>
          </div>

          <form id="notification-form">
            <div class="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications?</legend>
                <div class="radio-options">
                  <label class="radio-option">
                    <input type="radio" name="notification-preference" value="email" required>
                    <span>Email</span>
                  </label>
                  <label class="radio-option">
                    <input type="radio" name="notification-preference" value="sms">
                    <span>SMS</span>
                  </label>
                  <label class="radio-option">
                    <input type="radio" name="notification-preference" value="push-notifications">
                    <span>Push Notifications</span>
                  </label>
                </div>
              </fieldset>
            </div>

            <div class="actions">
              <button type="submit">Save preference</button>
              <p class="status" id="form-status" aria-live="polite"></p>
            </div>
          </form>
        </section>
      </main>
    </div>

    <script>
      const form = document.querySelector("#notification-form");
      const statusMessage = document.querySelector("#form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const formData = new FormData(form);
        const selectedPreference = formData.get("notification-preference");
        const selectedInput = form.querySelector(`input[value="${selectedPreference}"]`);
        const selectedLabel = selectedInput.closest("label").textContent.trim();

        statusMessage.textContent = `Preference saved: ${selectedLabel}.`;
      });
    </script>
  </body>
</html>
